import{_ as o,l as s,o as e,c as l,v as r,p as n,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"页与槽","description":"","frontmatter":{"title":"页与槽","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/page-slot.md","filePath":"cs/page-slot.md","lastUpdated":1789023840000}'),h={name:"cs/page-slot.md"};function E(A,a,_,B,m,f){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="页与槽" tabindex="-1">页与槽 <a class="header-anchor" href="#页与槽" aria-label="Permalink to &quot;页与槽&quot;">​</a></h1><div class="epigraph"><p>磁盘按页搬；页内用槽目录指向变长记录，元组身份才能与物理偏移分开。</p><footer>—— 据 Gray and Reuter, Transaction Processing；Ramakrishnan and Gehrke 对页组织的整理</footer></div><p><a href="/cs/covering-index">上一课</a>把外模式收到视图。本课不重讲物化维护。缺口是：关系最终要落在<a href="/cs/file-bytestream">文件字节流</a>上，而缓冲池按页换入换出。没有页内布局，就没有稳定的记录地址，索引只能指向「现在碰巧的偏移」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>操作系统的文件是字节序列；数据库需要定长页（常 4KiB 或 8KiB），与<a href="/cs/buffer-dirty">缓冲与脏页</a>对齐。页里若把记录紧密拼接，变长更新会移动后续字节，所有指针作废。缺口不是「再讲一遍文件」，而是<strong>页头 + 槽目录 + 记录空间</strong>：槽存偏移，记录可在页内滑动，对外只暴露页号与槽号。</p><p>本课不引入 B+ 树内部节点格式，那是索引课。这里只钉堆文件与索引页共用的槽化页。</p><p><span class="marginnote">记录标识 rid = (页号, 槽号)。槽号稳定，记录在页内搬家只改槽里的偏移。这是后课索引与堆文件的共同地址。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>页头记下空闲空间、槽个数、校验或 LSN（后课 WAL 才用）。槽目录从页尾向页头长，记录从页头向页尾长，中间是自由空间。删除把槽标空，或置删除位；空间可经整理收回。变长字段用偏移数组；超长字段溢出到溢出页，本课只承认有溢出，不把 TOAST 写完。</p>',9)),(e(),n(c,null,{default:t(()=>[p(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILE%5B%22%E6%96%87%E4%BB%B6%E5%AD%97%E8%8A%82%E6%B5%81%22%5D%20--%3E%20PAGE%5B%22%E5%AE%9A%E9%95%BF%E9%A1%B5%22%5D%0A%20%20PAGE%20--%3E%20SLOT%5B%22%E6%A7%BD%E7%9B%AE%E5%BD%95%22%5D%0A%20%20SLOT%20--%3E%20RID%5B%22rid%3A%20%E9%A1%B5%E5%8F%B7%2B%E6%A7%BD%E5%8F%B7%22%5D%0A%20%20RID%20--%3E%20HEAP%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%A0%86%E6%96%87%E4%BB%B6%E4%B8%8E%E8%81%9A%E7%B0%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>槽化使更新局部：加长记录若本页放不下，才迁移到新页并在原槽留转发，索引不必立刻全改（转发有代价）。定长记录可以取消槽，用算术算偏移；变长与空值一多，槽更合算。校验和与页 LSN 把「这一页的版本」钉死，崩溃后<a href="/cs/aries-recovery">ARIES</a>才知道页旧不旧。</p><p>本课不处理列存页、压缩页的全部变体；列存把属性切开，槽的含义变成列块，主干仍以行页为默认图像。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲磁盘调度、RAID。页大小是工程常数，与文件系统块可以不同，库自己做缓冲。也不把「一行一页」当默认——那是极端宽行或溢出。</p><p>行锁若以 rid 为粒度，槽重用必须与事务可见性对齐，否则会锁错对象——那是后课并发的交界，本课只把 rid 交出去。后课默认：元组有 rid；堆与索引都通过页与槽找记录，而不是通过文件的字节下标。</p><p>页是缓冲池与日志共同的粒度。后课 WAL 的 pageLSN 打在页头上，槽目录是页内的寻址，两者一起才构成可恢复的记录。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>视图已在逻辑层；本课把记录放进槽化页，交出 rid。</li><li>槽把身份与页内偏移分开，供索引与堆共用。</li><li>记录如何排成堆、何时按键聚簇，是后课缺口。</li><li>出处：Gray and Reuter；Ramakrishnan and Gehrke；Garcia-Molina, Ullman and Widom。</li></ul>',9))])}const S=o(h,[["render",E]]);export{T as __pageData,S as default};
